-- PlanFlow fictional October–December 2026 data. Run once in a new schema.

SET @previous_sql_mode = @@SESSION.sql_mode;

SET SESSION sql_mode = CONCAT_WS(',', NULLIF(@@SESSION.sql_mode,''), 'NO_BACKSLASH_ESCAPES');

CREATE DATABASE IF NOT EXISTS planflow_app_october_2026 CHARACTER SET utf8mb4;

USE planflow_app_october_2026;


CREATE TABLE departments (department_id INT PRIMARY KEY, department_name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE shifts (shift_id INT PRIMARY KEY, shift_name VARCHAR(30) NOT NULL UNIQUE, start_time VARCHAR(8) NOT NULL, end_time VARCHAR(8) NOT NULL);
CREATE TABLE daily_plans (
 plan_id INT PRIMARY KEY AUTO_INCREMENT,
 plan_date VARCHAR(10) NOT NULL,
 department_id INT NOT NULL ,
 shift_id INT NOT NULL ,
 forecast_cases INT NOT NULL CHECK(forecast_cases>=0),
 available_staff INT NOT NULL CHECK(available_staff>=0),
 cases_per_person_hour DECIMAL(8,2) NOT NULL CHECK(cases_per_person_hour>0),
 productive_hours DECIMAL(4,2) NOT NULL CHECK(productive_hours>0 AND productive_hours<=12),
 notes VARCHAR(200) NOT NULL DEFAULT '',
 version INT NOT NULL DEFAULT 1,
 FOREIGN KEY(department_id) REFERENCES departments(department_id), FOREIGN KEY(shift_id) REFERENCES shifts(shift_id), UNIQUE(plan_date,department_id,shift_id));
CREATE TABLE plan_extras (
 plan_id INT PRIMARY KEY,
 scheduled_staff INT NOT NULL CHECK(scheduled_staff>=0),
 absent_staff INT NOT NULL CHECK(absent_staff>=0 AND absent_staff<=scheduled_staff),
 paid_hours DECIMAL(4,2) NOT NULL CHECK(paid_hours>0 AND paid_hours<=12),
 overtime_hours DECIMAL(4,2) NOT NULL CHECK(overtime_hours>=0 AND overtime_hours<=4),
 hourly_cost DECIMAL(8,2) NOT NULL CHECK(hourly_cost>=0),
 overtime_rate DECIMAL(8,2) NOT NULL CHECK(overtime_rate>=0),
 dispatch_deadline VARCHAR(20) NOT NULL,
 actual_cases INT CHECK(actual_cases>=0),
 actual_staff INT CHECK(actual_staff>=0),
 actual_productive_hours DECIMAL(4,2) CHECK(actual_productive_hours>0 AND actual_productive_hours<=12),
 actual_finished_at VARCHAR(20), FOREIGN KEY(plan_id) REFERENCES daily_plans(plan_id));
CREATE TABLE scenarios (
 scenario_id INT PRIMARY KEY AUTO_INCREMENT,
 scenario_name VARCHAR(100) NOT NULL,
 plan_date VARCHAR(10) NOT NULL,
 shift_id INT NOT NULL ,
 created_at VARCHAR(25) NOT NULL,
 base_json TEXT NOT NULL,
 proposed_json TEXT NOT NULL,
 result_json TEXT NOT NULL, FOREIGN KEY(shift_id) REFERENCES shifts(shift_id));
CREATE TABLE audit_log (
 audit_id INT PRIMARY KEY AUTO_INCREMENT,
 changed_at VARCHAR(25) NOT NULL,
 action VARCHAR(40) NOT NULL,
 entity_id INT NOT NULL,
 before_json TEXT NOT NULL,
 after_json TEXT NOT NULL);


START TRANSACTION;






COMMIT;

SET SESSION sql_mode = @previous_sql_mode;
